\title{Rigidity of the Monstrous-Moonshine Head Product\\
\large From a Laurent coefficient to a complete finite invariant}
\author{Aristotle}
\date{25 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Monstrous Moonshine attaches to each of the $194$ conjugacy classes $g$ of the
Monster simple group a McKay--Thompson series
$T_g(q) = q^{-1} + 0 + c_g(1)q + c_g(2)q^2 + \cdots$, whose \emph{head table} is
the list of $194$ integers $c_g(1)$. We study the $194$-fold product
$P = \prod_g T_g$ in the field of formal Laurent series and prove three things.
First, a \emph{reduction}: for series in McKay--Thompson normalization the
Laurent coefficient of $P$ in degree $-192$ is exactly $\sum_g c_g(1)$ and the
coefficient in degree $-191$ is exactly $\sum_g c_g(2)$, so the assertion
``$[q^{-192}]P = S$'' is \emph{equivalent} to the decidable integer equation
$\sum_g c_g(1) = S$; the level-$3$ statement rests on a division-free Newton
identity. Second, a \emph{Vieta theorem}: the coefficient of $P$ in degree
$2k-194$ is the $k$-th elementary symmetric function of the head table. Third, a
\emph{rigidity theorem}: two integral head tables give the same product if and
only if they agree as multisets, so the product is a complete invariant of the
table up to relabelling and the reduction to arithmetic loses nothing; in
particular equality of two Monster-sized products is decidable. We complement
these with a division-free derivation of the identity-class entry
$c_{1A}(1) = 196884$ from $j = E_4^3/\Delta$ using only formal power series over
$\mathbb{Z}$, the first twelve Ramanujan tau values with their Hecke relations
and congruences, and an a priori bound confining the finite check to
$194 \pm 194\cdot 196883$.
\end{abstract}

\section{Introduction}

\subsection{Background}
The modular invariant
\[
  j(q) = \frac{1}{q} + 744 + 196884\,q + 21493760\,q^2 + 864299970\,q^3 + \cdots
\]
and the Monster sporadic simple group $\mathbb{M}$ are linked by McKay's
observation $196884 = 196883 + 1$, where $196883$ is the dimension of the
smallest faithful irreducible representation of $\mathbb{M}$. Conway and Norton's
Monstrous Moonshine conjecture extends the observation to all $194$ conjugacy
classes: to each class $g$ it attaches a \emph{McKay--Thompson series}
\[
  T_g(q) = \frac{1}{q} + 0 + c_g(1)\,q + c_g(2)\,q^2 + \cdots,
\]
predicted to generate the function field of a genus-zero subgroup of
$\mathrm{SL}_2(\mathbb{R})$, with $c_g(n) = \tr(g \mid V^\natural_n)$ for the
graded moonshine module. In particular $c_g(1) = 1 + \chi_{196883}(g)$, so the
\emph{head table} $(c_g(1))_g$ is a list of $194$ integers. The identity class
gives $T_{1A} = j - 744$, whence $c_{1A}(1) = 196884$.

\subsection{The question}
Head-layer statements can be packaged as statements about the single product
$P = \prod_g T_g$, an element with a pole of order $194$. We ask (i) which
arithmetic statements about the head table are \emph{equivalent} to statements
about the Laurent coefficients of $P$, and (ii) whether such a reduction is
lossy. The answers are: the coefficient in degree $2k-194$ \emph{is} the $k$-th
elementary symmetric function of the table (Theorem~\ref{thm:vieta}), and the
product determines the table up to permutation (Theorem~\ref{thm:rigidity}), so
nothing is lost.

\section{Normalized Laurent series}

Work in the field $\mathbb{C}((q))$ of formal Laurent series with integer
exponents and support bounded below; write $[q^n]f$ for the coefficient of $q^n$.

\begin{definition}[Trace series]
For $c : \mathbb{N} \to \mathbb{C}$, the associated trace series is
$T_c = q^{-1} + \sum_{n\ge0} c(n) q^n$.
\end{definition}

\begin{definition}[Normalized series and normalized part]
A Laurent series $f$ is \emph{normalized} if it vanishes in degrees $< -1$ and
$[q^{-1}]f = 1$. For normalized $f$ put $\widehat f := q f \in \mathbb{C}[[q]]$,
so $\widehat f(0) = 1$ and $[q^{n+1}]\widehat f = [q^n]f$ for $n \ge 0$.
\end{definition}

\begin{lemma}[Pole order of a product]\label{lem:bridge}
If $f_1,\dots,f_m$ are normalized, then
$\prod_{i} f_i = q^{-m}\prod_i \widehat{f_i}$, where the right-hand product is a
power series with constant term $1$. Hence the product has a pole of order
exactly $m$ with leading coefficient $1$, and for all $k \ge 0$
\begin{equation}\label{eq:bridge}
  [q^{\,k-m}]\prod_i f_i \;=\; [q^{k}]\prod_i \widehat{f_i}.
\end{equation}
\end{lemma}

\begin{proof}
Multiply the relations $\widehat{f_i} = q f_i$ and use multiplicativity of the
constant term.
\end{proof}

\begin{definition}[Head table and head product]
Let $t : \{1,\dots,194\}\to\mathbb{Z}$ be a \emph{head table}. Its head series
are $T^{(i)} = q^{-1} + t_i q$, and the \emph{head product} is
$P(t) = \prod_{i=1}^{194}(q^{-1} + t_i q)$.
\end{definition}

The head series is the truncation of $T_g$ to the data being checked: the pole
$q^{-1}$, the vanishing constant term demanded by McKay--Thompson normalization,
and the head coefficient $c_g(1) = t_i$.

\begin{lemma}\label{lem:norm-head}
$\widehat{T^{(i)}} = 1 + t_i q^2$, and hence
$q^{194}P(t) = \prod_{i=1}^{194}\bigl(1 + t_i q^2\bigr)$.
\end{lemma}

\section{Newton identities and the third coefficient}

\begin{theorem}[Newton identity at level 3]\label{thm:newton3}
Let $(g_i)_{i \in s}$ be a finite family of power series with $[q^0]g_i = 1$.
Write $a_r^{(i)} = [q^r]g_i$ and $p_r = \sum_i (a_1^{(i)})^r$. Then
\[
  6\,[q^3]\prod_{i\in s} g_i
  = 6\sum_i a_3^{(i)}
  + 6\Bigl[\Bigl(\sum_i a_1^{(i)}\Bigr)\Bigl(\sum_i a_2^{(i)}\Bigr) - \sum_i a_1^{(i)}a_2^{(i)}\Bigr]
  + \bigl(p_1^3 - 3p_1p_2 + 2p_3\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $s$. The empty case is trivial. For the step, expand
$[q^3](AB) = A_0B_3 + A_1B_2 + A_2B_1 + A_3B_0$ with $A = g_a$ and
$B = \prod_{i\in s} g_i$, substitute $A_0 = B_0 = 1$, the level-$1$ identity
$B_1 = \sum_{i\in s} a_1^{(i)}$, the level-$2$ identity for $B_2$ and the
inductive hypothesis for $B_3$. The difference of the two sides is the
inductive hypothesis plus $3a_1^{(a)}$ times the level-$2$ identity, so the step
closes as a linear combination of previously established identities.
\end{proof}

The bracketed term is the mixed second elementary symmetric expression in the
pairs $(a_1^{(i)},a_2^{(i)})$, and $\tfrac16(p_1^3 - 3p_1p_2 + 2p_3) = e_3(a_1)$.

\begin{theorem}[Third Laurent coefficient of a normalized product]\label{thm:third}
Let $f_1,\dots,f_m$ be normalized with $a_r^{(i)} = [q^r]f_i$ and
$p_r = \sum_i (a_0^{(i)})^r$. Then
\[
  6\,[q^{\,3-m}]\prod_i f_i
  = 6\sum_i a_2^{(i)}
  + 6\Bigl[\Bigl(\sum_i a_0^{(i)}\Bigr)\Bigl(\sum_i a_1^{(i)}\Bigr) - \sum_i a_0^{(i)}a_1^{(i)}\Bigr]
  + \bigl(p_1^3 - 3p_1p_2 + 2p_3\bigr).
\]
\end{theorem}

\begin{proof}
Apply \eqref{eq:bridge} with $k=3$ and Theorem~\ref{thm:newton3} to the
$\widehat{f_i}$, using $[q^{r+1}]\widehat{f_i} = a_r^{(i)}$.
\end{proof}

\begin{corollary}[McKay--Thompson normalization kills the corrections]\label{cor:mt}
If $a_0^{(i)} = c_i(0) = 0$ for all $i$, then for $m = 194$
\[
  [q^{-192}]\prod_{i=1}^{194} T_{c_i} = \sum_i c_i(1),
  \qquad
  [q^{-191}]\prod_{i=1}^{194} T_{c_i} = \sum_i c_i(2).
\]
\end{corollary}

\section{The reduction to a decidable integer equation}

\begin{theorem}[Reduction, coefficient form]\label{thm:reduction}
For every integral head table $t$, $[q^{-192}]P(t) = \sum_{i=1}^{194} t_i$.
\end{theorem}

\begin{proof}
The head series have vanishing constant coefficient, so Corollary~\ref{cor:mt}
applies with $c_i(1) = t_i$.
\end{proof}

\begin{theorem}[The head statement is finite arithmetic]\label{thm:iff}
For every integral head table $t$ and every $S \in \mathbb{Z}$,
\[
  [q^{-192}]P(t) = S \iff \sum_{i=1}^{194} t_i = S .
\]
\end{theorem}

\begin{proof}
Theorem~\ref{thm:reduction} and injectivity of
$\mathbb{Z}\hookrightarrow\mathbb{C}$.
\end{proof}

The right-hand side is decided by $193$ additions; the equivalence runs both
ways, so nothing is weakened. The analogous statement one level deeper, using
Corollary~\ref{cor:mt}, holds for the degree-$(-191)$ coefficient and the column
$(c_g(2))_g$.

\paragraph{A verified instance.} Section~\ref{sec:j} derives
$c_{1A}(1) = 196884$ with no external data. Combined with an illustrative table
whose remaining $193$ entries are the placeholder value $1$ (the value $c_g(1)$
would take at a class with $\chi_{196883}(g)=0$), the check reads
$\sum_i t_i = 196884 + 193 = 197077$, hence $[q^{-192}]P(t) = 197077$: an
equality between an infinite Laurent product and an integer, settled by
addition.

\section{Vieta for the moonshine product}

\begin{definition}
For $0 \le k \le 194$ set
$e_k(t) = \sum_{|T| = k} \prod_{i \in T} t_i$, the $k$-th elementary symmetric
function of the head table, with $e_0(t) = 1$.
\end{definition}

\begin{lemma}\label{lem:expand}
For a finite family $(a_i)_{i\in I}$ in a commutative ring,
$[q^{2k}]\prod_{i\in I}(1 + a_i q^2) = \sum_{|T| = k}\prod_{i \in T} a_i$, and all
odd coefficients vanish.
\end{lemma}

\begin{proof}
Distributing gives $\sum_{T \subseteq I}\bigl(\prod_{i\in T}a_i\bigr)q^{2|T|}$.
\end{proof}

\begin{theorem}[Vieta for the head product]\label{thm:vieta}
For every integral head table $t$ and every $k \ge 0$,
\[
  [q^{\,2k-194}]\,P(t) \;=\; e_k(t).
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:norm-head}, $q^{194}P(t) = \prod_i (1 + t_i q^2)$; extract the
coefficient of $q^{2k}$ using Lemma~\ref{lem:expand} and shift degrees.
\end{proof}

\begin{corollary}
$[q^{-194}]P(t) = 1$: the pole has order exactly $194$ and the product is monic
there, whatever the table. The case $k=1$ recovers
Theorem~\ref{thm:reduction}, and all coefficients in odd degrees relative to the
pole vanish.
\end{corollary}

Theorem~\ref{thm:vieta} identifies the whole Laurent spectrum of $P(t)$ with the
coefficient vector of the generating polynomial
\begin{equation}\label{eq:phi}
  \Phi_t(X) = \prod_{i=1}^{194}(X + t_i) = \sum_{k=0}^{194} e_k(t)\,X^{194-k}.
\end{equation}

\section{Rigidity: the product is a complete invariant}

Write $\mathcal{M}(t)$ for the multiset $\{\!\{t_1,\dots,t_{194}\}\!\}$.

\begin{lemma}[Permutation invariance]\label{lem:perm}
If $\mathcal{M}(t) = \mathcal{M}(u)$ then $P(t) = P(u)$.
\end{lemma}

\begin{proof}
The head product is the product of the multiset image of $t$ under
$x \mapsto q^{-1} + xq$; the product of a multiset does not depend on an
ordering.
\end{proof}

\begin{lemma}\label{lem:esymm}
If $P(t) = P(u)$ then $e_k(t) = e_k(u)$ for all $k$.
\end{lemma}

\begin{proof}
Apply $[q^{2k-194}](-)$ and use Theorem~\ref{thm:vieta}; the resulting equality
of complex numbers is an equality of integers.
\end{proof}

\begin{lemma}\label{lem:multiset}
If $e_k(t) = e_k(u)$ for all $k$, then $\mathcal{M}(t) = \mathcal{M}(u)$.
\end{lemma}

\begin{proof}
By \eqref{eq:phi} the monic degree-$194$ polynomials $\Phi_t,\Phi_u \in
\mathbb{C}[X]$ have identical coefficients, so $\Phi_t = \Phi_u$. Each is a
product of $194$ monic linear factors, so by unique factorization in
$\mathbb{C}[X]$ its multiset of roots with multiplicity is $\{\!\{-t_i\}\!\}$
resp.\ $\{\!\{-u_i\}\!\}$. Equality of the polynomials gives equality of the root
multisets; negate and use injectivity of $\mathbb{Z}\hookrightarrow\mathbb{C}$.
\end{proof}

\begin{theorem}[Rigidity of the head table]\label{thm:rigidity}
For integral head tables $t,u$,
\[
  P(t) = P(u) \iff \mathcal{M}(t) = \mathcal{M}(u).
\]
\end{theorem}

\begin{proof}
($\Leftarrow$) Lemma~\ref{lem:perm}. ($\Rightarrow$) Lemma~\ref{lem:esymm}
followed by Lemma~\ref{lem:multiset}.
\end{proof}

Thus $t \mapsto P(t)$ is injective on multisets: the $194$-fold product is a
\emph{complete} invariant of the head table up to relabelling, which is the
strongest possible statement since a product is symmetric in its factors.

\begin{corollary}[Separation by the finite check]
If $\sum_i t_i \ne \sum_i u_i$ then $P(t) \ne P(u)$.
\end{corollary}

\begin{corollary}[Decidability]
Equality of two $194$-fold McKay--Thompson head products is decidable: it is
equivalent to equality of two multisets of $194$ integers, tested in
$O(n\log n)$ by sorting.
\end{corollary}

\begin{remark}
The argument works because the head series has \emph{vanishing constant term}:
$\widehat{T^{(i)}} = 1 + t_i q^2$ is a specialization of the generic linear
factor $1 + t_i Y$ at $Y = q^2$. With non-zero constant terms $c_g(0)$ the
coefficients mix two columns of the table (Theorem~\ref{thm:third}) and the
clean Vieta statement fails. McKay--Thompson normalization is precisely what
makes the head layer rigid.
\end{remark}

\section{Deriving the identity-class entry from first principles}\label{sec:j}

\subsection{Setting}
In $\mathbb{Z}[[q]]$ define
\[
  E_4 = 1 + 240\sum_{n\ge1}\sigma_3(n)q^n, \qquad
  D_m = \prod_{k=1}^{m}(1-q^k)^{24},
\]
with $\sigma_3(n) = \sum_{d\mid n} d^3$, so that $\Delta = q D_\infty$ and
$j = E_4^3/\Delta$; equivalently $qj$ solves $D_\infty f = E_4^3$.

\subsection{Congruence calculus}
Write $f \equiv g \pmod {q^N}$ when $[q^n]f = [q^n]g$ for all $n < N$.

\begin{lemma}\label{lem:cong}
$f \equiv g \pmod{q^N}$ iff $q^N \mid f-g$. Hence the relation is an equivalence
compatible with sums, products and powers, and a unit factor may be cancelled.
\end{lemma}

\begin{proof}
Divisibility by $q^N$ is vanishing below degree $N$. Products:
$fg - f'g' = f(g-g') + g'(f-f')$. Cancellation by a unit $u$:
$f - g = u^{-1}(u(f-g))$.
\end{proof}

\begin{lemma}\label{lem:unit}
$[q^0]D_m = 1$, so $D_m$ is a unit of $\mathbb{Z}[[q]]$.
\end{lemma}

\begin{lemma}\label{lem:late}
If $N \le k$ then $(1-q^k)^{24}\equiv 1 \pmod {q^N}$, since $(1-q^k)-1 = -q^k$
divides $(1-q^k)^{24}-1$.
\end{lemma}

\begin{theorem}[Truncation stability]\label{thm:stab}
If $N \le m+1$ and $N \le m'+1$ then $D_m \equiv D_{m'} \pmod{q^N}$.
\end{theorem}

\begin{proof}
$D_{m+1} = D_m (1-q^{m+1})^{24}$, so by Lemma~\ref{lem:late} passing from
$D_{m+1}$ to $D_m$ changes nothing below degree $N$ once $m + 1 \ge N$; induct
down to $D_{N-1}$.
\end{proof}

Theorem~\ref{thm:stab} makes the infinite eta product well defined
coefficientwise with no convergence theory.

\begin{theorem}[Unique integral quotient]
For every $m$ there is a unique $f \in \mathbb{Z}[[q]]$ with $D_m f = E_4^3$,
namely $f = D_m^{-1}E_4^3$; its coefficients are integers, and by
Theorem~\ref{thm:stab} they are independent of $m$ below degree $m+1$.
\end{theorem}

\begin{theorem}[Window uniqueness]\label{thm:window}
Let $N \le m+1$, $N\le m'+1$. If $E_4^3 \equiv D_m f$ and
$E_4^3 \equiv D_{m'} g \pmod{q^N}$, then $f \equiv g \pmod{q^N}$.
\end{theorem}

\begin{proof}
Combine with Theorem~\ref{thm:stab} to get $D_m f \equiv D_m g$ and cancel the
unit $D_m$ (Lemmas~\ref{lem:cong},~\ref{lem:unit}).
\end{proof}

\subsection{The verified window}
Finite convolution of integer coefficient lists establishes
\begin{align*}
E_4^3 \;\equiv\; D_{11}\cdot\bigl(&1 + 744q + 196884q^2 + 21493760q^3 + 864299970q^4 + 20245856256 q^5\\
&+ 333202640600q^6 + 4252023300096q^7 + 44656994071935q^8\\
&+ 401490886656000q^9 + 3176440229784420q^{10} + 22567393309593600q^{11}\bigr)
\end{align*}
modulo $q^{12}$. By Theorem~\ref{thm:window} \emph{every} solution of
$D_m f = E_4^3$ with $m \ge 11$ has these twelve coefficients, whence
$j = q^{-1} + 744 + 196884q + \cdots + 22567393309593600q^{10} + O(q^{11})$.

\begin{theorem}[Identity-class head entry]
$c_{1A}(1) = [q^1](j - 744) = 196884$, and McKay's identity
$196884 = 1 + 196883$ holds on this derived value.
\end{theorem}

\begin{theorem}[Tau values]
For $m \ge 11$ and $1\le n\le 12$, $[q^{n-1}]D_m = \tau(n)$, with
\[
  (\tau(1),\dots,\tau(12)) = (1,-24,252,-1472,4830,-6048,-16744,84480,-113643,-115920,534612,-370944).
\]
\end{theorem}

\begin{proposition}[Structure on the derived values]
$\tau(2)\tau(3) = \tau(6)$, $\tau(2)\tau(5)=\tau(10)$, $\tau(3)\tau(4)=\tau(12)$,
$\tau(4) = \tau(2)^2 - 2^{11}$, $\tau(9) = \tau(3)^2 - 3^{11}$,
$\tau(8) = \tau(2)\tau(4) - 2^{11}\tau(2)$; moreover
$\tau(n) \equiv \sigma_{11}(n) \pmod{691}$ and $\tau(n) \ne 0$ for
$1 \le n \le 12$, the first window of Lehmer's conjecture.
\end{proposition}

\begin{proposition}[McKay decompositions]
With $d_1 = 1$, $d_2 = 196883$, $d_3 = 21296876$, $d_4 = 842609326$,
$d_5 = 19360062527$, $d_6 = 293553734298$ and $c(n) = [q^n](j-744)$,
\[
  c(1) = d_1+d_2,\quad c(2) = d_1+d_2+d_3,\quad c(3) = 2d_1+2d_2+d_3+d_4,
\]
\[
  c(4) = 2d_1+3d_2+2d_3+d_4+d_5,\qquad
  c(5) = 3d_1+5d_2+4d_3+d_4+2d_5+d_6 .
\]
\end{proposition}

\section{A priori bounds on the finite check}

\begin{theorem}\label{thm:bound}
Let $t$ be an integral head table and $B \ge 0$ with $|t_i - 1|\le B$ for all
$i$. Then $\bigl|\sum_{i=1}^{194} t_i - 194\bigr| \le 194 B$.
\end{theorem}

\begin{proof}
$\sum_i t_i - 194 = \sum_i (t_i-1)$; apply the triangle inequality.
\end{proof}

\begin{corollary}
Under moonshine's prediction $c_g(1) = 1 + \chi_{196883}(g)$ one has $B = 196883$
and hence $194 - 38195302 \le \sum_i t_i \le 194 + 38195302$; a proposed table
outside $[-38195108,\,38195496]$ is refuted with no modular input.
\end{corollary}

\begin{remark}
The derived entry satisfies $|c_{1A}(1) - 1| = 196883$, exactly the extreme
permitted by Theorem~\ref{thm:bound}: the numerical fingerprint of a character
attaining its maximum modulus at the identity.
\end{remark}

\section{Algorithms}

\paragraph{A. Truncated series arithmetic over $\mathbb{Z}$.}
Represent a series modulo $q^N$ by $N$ integers and multiply by Cauchy
convolution $(a\ast b)_n = \sum_{k\le n} a_k b_{n-k}$ at cost $O(N^2)$. By
Lemma~\ref{lem:late} the eta product may be cut at $m = N-1$; each factor
$(1-q^k)^{24}$ is raised by repeated squaring.

\paragraph{B. Symmetric invariants of the head table.}
Compute all $e_k(t)$ by the incremental recursion
$e_k \leftarrow e_k + t_i e_{k-1}$ (scanning $k$ downwards) as $i$ runs over the
table, at cost $O(n^2)$ big-integer multiplications; by Theorem~\ref{thm:vieta}
the resulting vector \emph{is} the list of Laurent coefficients of the moonshine
product in degrees $-194,-192,\dots,194$.

\paragraph{C. Deciding equality of two products.}
By Theorem~\ref{thm:rigidity}, sort both tables and compare, $O(n\log n)$.

\section{Discussion}

The head layer of Monstrous Moonshine is, after the reduction, a statement about
$194$ integers. Three features matter. \emph{Equivalence, not implication}:
Theorem~\ref{thm:iff} is an ``if and only if''. \emph{Completeness}:
Theorem~\ref{thm:rigidity} shows the product is a complete invariant of the
table up to permutation, so the check cannot be fooled by a rearranged or
perturbed table. \emph{Derivability of the input}: Section~\ref{sec:j} produces
one entry rather than assuming it, using only unit-ness of the eta product and a
congruence calculus.

Limitations are equally clear. Moonshine proper --- the genus-zero property, the
modularity of every $T_g$, the graded module --- is beyond any finite check; it
was established by Borcherds in 1992. The reduction takes the head table as
input; nothing here derives the $193$ non-identity entries. Finally, the head
series of Sections 5--6 truncate $T_g$ after the $c_g(1)$ term: faithful for the
head layer by Theorem~\ref{thm:third}, but the Vieta description of \emph{all}
coefficients concerns the truncated product.

Mathematically, Sections 5--6 specialize the fundamental theorem of symmetric
functions: a multiset is determined by its elementary symmetric functions. What
is added is the dictionary --- for McKay--Thompson-normalized series those
functions are literally Laurent coefficients, in degrees $2k-n$.

\section{Future directions}

\paragraph{D1. Certificates for the full head table.}
Conjecturally every head coefficient $c_g(1)$ is computable by the same
eta-product mechanism used here for the identity class: for each class an eta
quotient $\prod_d \eta(d\tau)^{r_d}$ (plus an additive constant) whose
$q$-expansion truncated at $q^8$ has $q$-coefficient $c_g(1)$, checkable by
finite integer arithmetic. The mechanism never needs modularity: an eta quotient
is a unit times a power of $q$ in $\mathbb{Z}[[q]]$, so its coefficients are
forced by formal algebra. The machinery of Section~\ref{sec:j} is parametric in
the exponent vector; only the exponent data per class is missing. If the
conjecture holds, the whole table becomes derived data; if some class admits no
eta-quotient generator, the failing classes isolate where genuinely modular
input is unavoidable.

\paragraph{D2. The symmetric-function spectrum.}
Conjecturally $e_k(t) \ne 0$ for all $k \le 194$ and $|e_k|$ is strictly
log-concave. Theorem~\ref{thm:vieta} turns this analytic-looking question into
Newton's inequalities $e_{k-1}e_{k+1}\le e_k^2$ (after binomial normalization)
for the real-rooted polynomial $\Phi_t$, i.e.\ into a finite computation.

\paragraph{D3. Deeper Laurent layers.}
Theorem~\ref{thm:third} handles degree $3-m$. A division-free Newton identity
uniform in the level $r$, collapsing under McKay--Thompson normalization to
$\sum_g c_g(r-1)$, would extend the reduction to any fixed depth.

\paragraph{D4. Sharper separation.}
Quantify how many coefficients of the product must be inspected to separate two
tables differing in a single entry by one, giving a minimal effective
certificate.

