"""Division-free derivation of the q-expansion of j = E4^3 / Delta over Z."""
from __future__ import annotations
from typing import List, Sequence


def ps_mul(a: Sequence[int], b: Sequence[int], n_terms: int) -> List[int]:
    """Cauchy convolution truncated to n_terms coefficients.  Cost O(n_terms^2)."""
    out: List[int] = [0] * n_terms
    for i in range(min(len(a), n_terms)):
        if a[i]:
            for j in range(min(len(b), n_terms - i)):
                out[i + j] += a[i] * b[j]
    return out


def ps_pow(a: Sequence[int], e: int, n_terms: int) -> List[int]:
    """Repeated squaring; O(log e) convolutions."""
    res: List[int] = [1] + [0] * (n_terms - 1)
    base: List[int] = list(a[:n_terms]) + [0] * max(0, n_terms - len(a))
    while e:
        if e & 1:
            res = ps_mul(res, base, n_terms)
        base = ps_mul(base, base, n_terms)
        e >>= 1
    return res


def ps_inv(a: Sequence[int], n_terms: int) -> List[int]:
    """Inverse of a unit series (constant term 1).  Cost O(n_terms^2)."""
    assert a[0] == 1
    inv: List[int] = [1] + [0] * (n_terms - 1)
    for n in range(1, n_terms):
        inv[n] = -sum(a[k] * inv[n - k] for k in range(1, n + 1) if k < len(a))
    return inv


def sigma3(n: int) -> int:
    return sum(d ** 3 for d in range(1, n + 1) if n % d == 0)


def eisenstein_E4(n_terms: int) -> List[int]:
    """E4 = 1 + 240 sum_{n>=1} sigma_3(n) q^n."""
    return [1] + [240 * sigma3(n) for n in range(1, n_terms)]


def eta_product(m: int, n_terms: int) -> List[int]:
    """D_m = prod_{k=1}^{m} (1 - q^k)^24, truncated."""
    out: List[int] = [1] + [0] * (n_terms - 1)
    for k in range(1, m + 1):
        factor: List[int] = [1] + [0] * (n_terms - 1)
        if k < n_terms:
            factor[k] = -1
        out = ps_mul(out, ps_pow(factor, 24, n_terms), n_terms)
    return out


def j_expansion(n_terms: int) -> List[int]:
    """Coefficients of q*j: the unique integral solution of D * f = E4^3.

    By truncation stability the cut-off m = n_terms - 1 is already exact below
    degree n_terms, and D is a unit of Z[[q]] because its constant term is 1,
    so no denominators ever appear.
    """
    e4 = eisenstein_E4(n_terms)
    e4_cubed = ps_mul(ps_mul(e4, e4, n_terms), e4, n_terms)
    delta = eta_product(max(n_terms - 1, 1), n_terms)
    return ps_mul(e4_cubed, ps_inv(delta, n_terms), n_terms)


if __name__ == "__main__":
    coeffs = j_expansion(12)
    print("q*j =", coeffs)
    print("identity-class head entry c_1A(1) =", coeffs[2])
    print("tau(1..12) =", eta_product(11, 12))

