INPUT: t[1..n], an integral head table
OUTPUT: e[0..n], with e[k] = [q^{2k-n}] prod_i (q^{-1} + t_i q)

1. e[0] <- 1; e[k] <- 0 for k = 1..n
2. for i = 1 to n do                       // multiply by (1 + t_i Y)
3.     for k = i down to 1 do              // downward, so e[k-1] is still old
4.         e[k] <- e[k] + t[i] * e[k-1]
5. return e

// Laurent dictionary: degree(k) = 2k - n; odd degrees relative to the pole vanish.
// e[0] = 1  : pole of order exactly n, monic.
// e[1]      : the finite head check, sum_i t_i, in degree 2 - n.

