"""Deciding equality of two Monster-sized McKay-Thompson head products."""
from __future__ import annotations
from typing import List, Optional, Sequence, Tuple


def canonical_form(t: Sequence[int]) -> Tuple[int, ...]:
    """Sorted table: a canonical representative of the multiset.  O(n log n)."""
    return tuple(sorted(t))


def products_equal(t: Sequence[int], u: Sequence[int]) -> bool:
    """Decide prod_g (q^-1 + t_g q) = prod_g (q^-1 + u_g q).

    Rigidity: the 194-fold product is a complete invariant of the head table up
    to relabelling, so the infinite Laurent equality is equivalent to equality
    of two multisets of integers.
    """
    return canonical_form(t) == canonical_form(u)


def elementary_symmetric(t: Sequence[int]) -> List[int]:
    e: List[int] = [0] * (len(t) + 1)
    e[0] = 1
    for i, ti in enumerate(t, start=1):
        for k in range(i, 0, -1):
            e[k] += ti * e[k - 1]
    return e


def separating_degree(t: Sequence[int], u: Sequence[int]) -> Optional[int]:
    """The first Laurent degree at which the two products differ, or None.

    Returns 2k - n for the least k with e_k(t) != e_k(u).  Cost O(n^2); the
    cheap test above should be used first, this one exhibits the witness.
    """
    if len(t) != len(u):
        raise ValueError("tables must have the same length")
    et, eu = elementary_symmetric(t), elementary_symmetric(u)
    for k, (a, b) in enumerate(zip(et, eu)):
        if a != b:
            return 2 * k - len(t)
    return None


if __name__ == "__main__":
    base: List[int] = [196884] + [1] * 193
    permuted: List[int] = base[::-1]
    perturbed: List[int] = base[:]
    perturbed[7] += 1
    sum_preserving: List[int] = base[:]
    sum_preserving[7] += 5
    sum_preserving[8] -= 5
    for name, cand in (("permuted", permuted), ("perturbed", perturbed),
                       ("sum-preserving", sum_preserving)):
        print(f"{name:16s} equal = {products_equal(base, cand)!s:5s} "
              f"first differing degree = {separating_degree(base, cand)}")
